import React, { useState, useEffect } from 'react';
import { 
  Trash2, Map, Calendar, Star, LineChart, Users, 
  HardHat, FileText, Activity, ShieldAlert, ChevronLeft, AlertCircle,
  Cpu, Wifi, Lock
} from 'lucide-react';

const Dashboard = () => {
  const [currentView, setCurrentView] = useState('MENU');
  const [isPoweringOn, setIsPoweringOn] = useState(true);

  // Power-on sequence effect
  useEffect(() => {
    const timer = setTimeout(() => setIsPoweringOn(false), 1000);
    return () => clearTimeout(timer);
  }, []);

  const allTabs = [
    { id: 'BINS', label: '01_BIN_MONITORING', icon: <Trash2 size={32}/>, color: '#CAD23C' },
    { id: 'ZONES', label: '02_AREAS_&_ZONES', icon: <Map size={32}/>, color: '#FDFAD8' },
    { id: 'SCHEDULE', label: '03_COLL_SCHEDULE', icon: <Calendar size={32}/>, color: '#A1AED1' },
    { id: 'POINTS', label: '04_REWARDS_POINTS', icon: <Star size={32}/>, color: '#CAD23C' },
    { id: 'ANALYTICS', label: '05_SYS_ANALYTICS', icon: <LineChart size={32}/>, color: '#FDFAD8' },
    { id: 'CITIZENS', label: '06_CITIZEN_INFO', icon: <Users size={32}/>, color: '#A1AED1' },
    { id: 'WORKERS', label: '07_WORKER_NODES', icon: <HardHat size={32}/>, color: '#CAD23C' },
    { id: 'REPORTS', label: '08_SYS_REPORTS', icon: <FileText size={32}/>, color: '#FDFAD8' },
  ];

  if (isPoweringOn) {
    return (
      <div className="w-full h-screen bg-[#47510B] flex items-center justify-center">
        <div className="w-1 h-1 bg-[#CAD23C] rounded-full animate-ping" />
        <p className="ml-4 font-mono text-[#CAD23C] animate-pulse tracking-[0.5em] text-xs">BOOTING_CORE_V3...</p>
      </div>
    );
  }

  return (
    <div className="w-full min-h-screen bg-[#FDFAD8] p-4 md:p-10 flex items-center justify-center font-sans overflow-x-hidden relative">

      {/* SCAN-LINE OVERLAY (The "CRT" Look) */}
      <div className="fixed inset-0 pointer-events-none opacity-[0.03] z-50 bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,118,0.06))] bg-[length:100%_2px,3px_100%]" />

      <div className="w-full max-w-[1300px] flex flex-col gap-8 transition-all duration-700 ease-out">

        {/* --- BLOCK 1: THE COMMAND HEADER --- */}
        <div className="bg-[#AB1717] border-[8px] border-[#47510B] rounded-t-[60px] rounded-b-[20px] p-8 relative overflow-hidden red-stack-shadow">
          {/* Animated Background Glow */}
          <div className="absolute -top-24 -left-24 w-64 h-64 bg-[#CAD23C] opacity-10 blur-[80px] animate-pulse" />

          <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-6">
            <div className="flex items-center gap-6">
              <div className="bg-[#47510B] p-4 rounded-3xl border-2 border-[#CAD23C]/30 shadow-2xl rotate-3 hover:rotate-0 transition-transform cursor-crosshair">
                <ShieldAlert size={40} className="text-[#CAD23C]" strokeWidth={2.5} />
              </div>
              <div className="text-center md:text-left">
                <div className="flex items-center gap-2 mb-1 justify-center md:justify-start">
                  <span className="w-2 h-2 bg-[#CAD23C] rounded-full animate-ping" />
                  <p className="text-[10px] font-black uppercase tracking-[0.6em] text-[#FDFAD8] opacity-70 italic">Command.Center.Live</p>
                </div>
